						_TIFFmemcpy(val, &v, tv_size);
					}
					break;
				case TIFF_LONG:
				case TIFF_IFD:
					{
						uint32 v = va_arg(ap, uint32);
						_TIFFmemcpy(val, &v, tv_size);
					}
					break;
				case TIFF_SLONG:
					{
						int32 v = va_arg(ap, int32);
						_TIFFmemcpy(val, &v, tv_size);
					}
					break;
				case TIFF_LONG8:
				case TIFF_IFD8:
					{
						uint64 v = va_arg(ap, uint64);
						_TIFFmemcpy(val, &v, tv_size);
					}
					break;
				case TIFF_SLONG8:
					{
						int64 v = va_arg(ap, int64);
						_TIFFmemcpy(val, &v, tv_size);
					}
					break;
				case TIFF_RATIONAL:
				case TIFF_SRATIONAL:
				case TIFF_FLOAT:
					{
